// Loads the data generated by tools/site/build.py (python -m tools.site.build).
import fs from 'node:fs';
import path from 'node:path';

const GEN = path.resolve('./src/generated');
const read = (rel: string) => fs.readFileSync(path.join(GEN, rel), 'utf8');

export const base = (): string => {
  const b = import.meta.env.BASE_URL || '/';
  return b.endsWith('/') ? b : b + '/';
};
/** Absolute URL path inside the site, respecting the base path. */
export const u = (p = ''): string => base() + p.replace(/^\//, '');
/** Generated HTML uses %BASE% as a placeholder for the base path. */
export const fix = (html: string): string =>
  html.replaceAll('%BASE%', base())
    // Code blocks can scroll sideways in the content column, so keyboard users must be able to focus them.
    .replace(/<pre(?![^>]*\btabindex=)/g, '<pre tabindex="0"');

export interface Week {
  n: number; slug: string; title: string; idea: string; concepts: string; unplugged: string;
  objectives: string[]; vocab: { term: string; def: string }[];
  toc: { level: number; id: string; text: string }[];
  has_homework: boolean; homework_title: string; homework_note: string;
  exercises: { slug: string; title: string; number: string; kind: string; homework: boolean; url: string }[];
  downloads: Record<string, { url: string; kb: number }>;
  /** The teaching video, when tools/site/videos.py found one for this week. */
  video?: { src: string; poster: string; captions: string; seconds: number; minutes: number; mb: number;
    transcript: string[] };
}
export interface Level {
  /** Track id from curriculum.json ("main" for Grades 4-5, "junior" for Grades 2-3) and the level's key ("1", "j1"). */
  track: string; key: string;
  /** How pages name the level: "Level 1" or "Junior Level 1". */
  label: string; weeks_total: number; buffers: number; glossary_title?: string;
  number: number; slug: string; dir: string; name: string; languages: string; tools: string;
  goals: { code: string; text: string }[]; project_title: string; project_html: string;
  published: boolean; weeks: Week[]; downloads: Record<string, Record<string, { url: string; kb: number }>>;
  syllabus_weeks: { n: number; title: string; idea: string }[];
  project?: { title: string; toc: { level: number; id: string; text: string }[]; starter_readme: string;
    starter_files: { name: string; html: string; url: string }[]; zip: { url: string; kb: number } | null } | null;
  extras?: Record<string, { title: string; subtitle: string; toc: { level: number; id: string; text: string }[] }>;
  extra_downloads?: Record<string, Record<string, { url: string; kb: number }>>;
  glossary_count?: number;
}
export interface GlossaryEntry { term: string; key: string; where: string; meaning: string; example: string }
export interface Track { id: string; title: string; grades: string; ages: string; levels: string[] }
/** Every published level of every track (main track first). */
export const levels = (): Level[] => JSON.parse(read('levels.json'));
/** The tracks that have levels on the site, in curriculum.json order. */
export const tracks = (): Track[] => JSON.parse(read('tracks.json'));
export const trackLevels = (track: string): Level[] => levels().filter((l) => l.track === track);
export const isJunior = (l: Level): boolean => l.track === 'junior';
export const siteInfo = (): { version: string; updated: string; commit: string; changelog_html?: string } =>
  JSON.parse(read('site.json'));
export const parentsData = () => JSON.parse(read('parents.json'));
export const weekHtml = (slug: string, weekSlug: string) => fix(read(`html/${slug}/${weekSlug}.html`));
export const homeworkHtml = (slug: string, weekSlug: string) =>
  fix(read(`html/${slug}/homework-${weekSlug.replace('week-', '')}.html`));
export const levelHtml = (slug: string, name: string) => fix(read(`html/${slug}/${name}.html`));
export const glossary = (slug: string): GlossaryEntry[] => JSON.parse(read(`glossary/${slug}.json`));
export const resources = (): { slug: string; title: string; toc: { id: string; text: string }[] }[] => JSON.parse(read('resources.json'));
/** Absolute address of the site (with the base path), for text that people copy and paste. */
export const siteUrl = (): string => {
  const origin = String(import.meta.env.SITE || 'http://localhost:4321').replace(/\/$/, '');
  return origin + base();
};
export const resourceHtml = (slug: string) => fix(read(`html/resources/${slug}.html`)).replaceAll('%SITE%', siteUrl());
export const exercises = (slug: string) => {
  const dir = path.join(GEN, 'exercises', slug);
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).filter((f) => f.endsWith('.json')).map((f) => JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')));
};
export const LEVEL_COLORS: Record<number, string> = { 1: 'l1', 2: 'l2', 3: 'l3' };
